const input=$json??{};
const decision=String(input.decision??input.outcome??'').toLowerCase();
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
const seller=input.seller??{}; const sellerPhone=String(seller.phone??input.seller_phone??'').trim(); const sellerEmail=String(seller.email??input.seller_email??'').trim();
const dnc=Boolean(input.dnc??input.do_not_contact??false); const blockers=Array.isArray(input.blockers)?input.blockers:[];
const attempts=Number(input.reengagement_attempts??input.attempts??0); const maxAttempts=Number(input.max_reengagement_attempts??3);
const lastContactAt=input.last_contact_at??input.last_outbound_at??null;
const cadence=attempts<=0?'24h':attempts===1?'72h':'7d';
const identityComplete=Boolean(dealId&&leadId&&propertyId); const contactComplete=Boolean(sellerPhone||sellerEmail);
let status='needs_review'; let nextWorkflow='WF-344'; let action='review'; let reason='Seller re-engagement requires review.';
if(dnc){status='dnc_blocked';action='stop';nextWorkflow='WF-126';reason='Seller is on DNC; no re-engagement permitted.';}
else if(blockers.length){status='blocked';action='stop';nextWorkflow='WF-126';reason='Active blocker prevents seller re-engagement.';}
else if(!identityComplete||!contactComplete){status='incomplete';action='repair_data';nextWorkflow='WF-344';reason='Required deal identity or seller contact is missing.';}
else if(attempts>=maxAttempts){status='max_attempts_reached';action='pause';nextWorkflow='WF-126';reason='Maximum re-engagement attempts reached; human review required.';}
else if(['reengagement_ready','rejection_reengagement','rejection','no_response','timeout_reengagement'].includes(decision)){status='reengagement_ready';action='schedule_reengagement';nextWorkflow='WF-346';reason='Seller outcome qualifies for controlled re-engagement cadence.';}
else{status='not_applicable';action='review';nextWorkflow='WF-344';reason='Current outcome does not require re-engagement.';}
const activity={activity_type:'seller_reengagement_controller',subject:'WF-345 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,status,action,next_workflow:nextWorkflow,reengagement_attempts:attempts,max_reengagement_attempts:maxAttempts,cadence,seller_phone:sellerPhone,seller_email:sellerEmail,last_contact_at:lastContactAt,dnc,blockers,reason};
return [{json:{...input,wf_id:'WF-345',status,action,next_workflow:nextWorkflow,reengagement_attempts:attempts,max_reengagement_attempts:maxAttempts,cadence,last_contact_at:lastContactAt,dnc,blockers,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
